CREATE TABLE `send_outbox_archive` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `send_key` varchar(120) NOT NULL,
  `bid_key` varchar(40) NOT NULL,
  `template_id` varchar(40) NOT NULL,
  `receiver` varchar(255) NOT NULL,
  `payload_json` longtext DEFAULT NULL,
  `status` enum('NEW','SENDING','SENT','FAILED','SKIPPED') NOT NULL DEFAULT 'NEW',
  `try_count` int(11) NOT NULL DEFAULT 0,
  `last_error` text DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `sent_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_send_key` (`send_key`),
  UNIQUE KEY `ux_send_outbox_send_key` (`send_key`),
  KEY `idx_status_time` (`status`,`updated_at`),
  KEY `idx_bid` (`bid_key`)
) ENGINE=InnoDB AUTO_INCREMENT=66 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
